// Example of demonstrating senior-level awareness in an interview
// Instead of just 'I write fast code', explain why you chose a specific concurrency utility:

public class OrderProcessor {
    // Using ConcurrentHashMap for thread-safe, non-blocking reads
    private final Map<String, Order> cache = new ConcurrentHashMap<>();

    public void process(Order order) {
        // Demonstrating awareness of atomicity and race conditions
        cache.computeIfAbsent(order.getId(), id -> {
            // Expensive DB call happens only once per key
            return repository.save(order);
        });
    }
}
